<script setup lang="ts">
import {ref} from 'vue'
import {onLoad} from '@dcloudio/uni-app'
import {api,type Row} from '../../api/iot'
import BusinessForm,{type Field} from '../../components/BusinessForm.vue'
import {showError} from '../../utils/ui'
const id=ref(0),form=ref<Row>({ruleName:'',metricKey:'',deviceType:null,operator:'>',threshold:'',durationSeconds:0,level:'major',enabled:true,remark:'',sourceRuleId:null}),options=ref<Row>({metrics:[],deviceTypes:[],operators:[],levels:[]}),busy=ref(false),loaded=ref(false),error=ref('')
const fields=ref<Field[]>([])
function refreshFields(){fields.value=[{key:'ruleName',label:'规则名称',required:true},{key:'metricKey',label:'监控指标',type:'select',required:true,options:(options.value.metrics||[]).map((m:Row)=>({value:m.key,label:`${m.name}（${m.key}）`}))},{key:'deviceType',label:'设备类型',type:'select',options:[{value:null,label:'全部设备'},...(options.value.deviceTypes||[]).map((x:string)=>({value:x,label:x}))]},{key:'operator',label:'比较方式',type:'select',options:(options.value.operators||[]).map((x:string)=>({value:x,label:x}))},{key:'threshold',label:'阈值',required:true,type:'number'},{key:'durationSeconds',label:'持续时间（秒）',type:'number',hint:'0～86400'},{key:'level',label:'告警等级',type:'select',options:(options.value.levels||[]).map((x:string)=>({value:x,label:x}))},{key:'remark',label:'备注',type:'textarea'},{key:'enabled',label:'启用',type:'switch'}]}
onLoad(async o=>{id.value=Number(o?.id||0);uni.setNavigationBarTitle({title:id.value?'编辑主体阈值':'新增主体阈值'});try{options.value=await api.alertRuleOptions();if(id.value){const view=await api.alertRuleView();const current=(view.tenant||[]).find((r:Row)=>r.id===id.value);if(current)form.value={...form.value,...current}}refreshFields();loaded.value=true}catch(e){error.value=e instanceof Error?e.message:'规则加载失败'}})
async function save(){if(busy.value)return;try{if(!form.value.ruleName.trim()||!form.value.metricKey||form.value.threshold==='')throw new Error('请填写规则名称、指标和阈值');const n=Number(form.value.threshold),d=Number(form.value.durationSeconds);if(!Number.isFinite(n)||!Number.isInteger(d)||d<0||d>86400)throw new Error('阈值须为数字，持续时间须为 0～86400 的整数秒');busy.value=true;if(id.value)await api.updateAlertRule(id.value,form.value);else await api.createAlertRule(form.value);uni.showToast({title:'阈值规则已保存'});uni.navigateBack()}catch(e){showError(e)}finally{busy.value=false}}
</script><template><view class="page pad has-footer"><view v-if="error" class="error">{{error}}</view><view v-if="!loaded&&!error" class="loading">正在加载…</view><view v-if="loaded" class="card"><BusinessForm v-model="form" :fields="fields" :busy="busy" submit-text="保存阈值规则" @save="save"/></view></view></template>
